import { spawn, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import net from 'node:net';
import os from 'node:os';

const sol = path.resolve(process.argv[2]);
const server = path.join(sol, 'server.mjs');
const results = [];
const check = (name, ok, extra = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${ok ? '' : extra}`);

function tmp() { return fs.mkdtempSync(path.join(os.tmpdir(), 'pr-')); }

function runSync(env, cwd) {
  const r = spawnSync('node', [server], { env: { ...process.env, ...env }, cwd, timeout: 3000, encoding: 'utf8' });
  return r;
}

function start(env, cwd) {
  return new Promise((res, rej) => {
    const p = spawn('node', [server], { env: { ...process.env, PORT: '0', ...env }, cwd });
    let out = '';
    p.stdout.on('data', (d) => {
      out += d;
      const m = out.match(/listening on http:\/\/127\.0\.0\.1:(\d+)\n/);
      if (m) res({ p, port: Number(m[1]), out: () => out });
    });
    p.on('exit', (c) => rej(new Error('exited ' + c)));
  });
}

function raw(port, text) {
  return new Promise((res) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = '';
    s.on('data', (d) => (buf += d));
    s.on('end', () => res(buf));
    s.on('error', () => res(buf));
    s.write(text);
    setTimeout(() => { s.destroy(); res(buf); }, 1500);
  });
}

async function req(port, method, p, body, headers = {}) {
  const r = await fetch(`http://127.0.0.1:${port}${p}`, { method, body, headers });
  const t = await r.text();
  let j; try { j = JSON.parse(t); } catch {}
  return { status: r.status, j, t, ct: r.headers.get('content-type') };
}
