r = runSync({ PORT: '65536' }, d); check('port>65535', r.status === 1);
r = runSync({ PORT: '+80' }, d); check('port +80', r.status === 1);
r = runSync({ PORT: '0', DATA_FILE: '.' }, d); check('dir data', r.status === 1 && r.stderr === 'cannot read data file .\n', JSON.stringify(r.stderr));
fs.writeFileSync(path.join(d, 'empty.json'), '');
r = runSync({ PORT: '0', DATA_FILE: 'empty.json' }, d); check('empty data', r.status === 1 && r.stderr === 'cannot read data file empty.json\n');
fs.writeFileSync(path.join(d, 'arr.json'), '[]');
r = runSync({ PORT: '0', DATA_FILE: 'arr.json' }, d); check('array data', r.status === 1);
r = runSync({ PORT: 'x', DATA_FILE: '.' }, d); check('port checked first', r.status === 1 && !r.stderr.includes('cannot read'));
// port in use
const blocker = net.createServer().listen(0, '127.0.0.1');
await new Promise((x) => blocker.once('listening', x));
r = runSync({ PORT: String(blocker.address().port), DATA_FILE: path.join(d, 'z.json') }, d);
check('port in use', r.status === 1 && r.stdout === '' && r.stderr.length > 0, JSON.stringify(r.stderr));
blocker.close();

// running
const { p, port, out } = await start({ DATA_FILE: 'sub/../b.json' }, d);
let x = await req(port, 'GET', '/api/rooms'); check('rooms', x.status === 200 && x.j.rooms.join() === 'Aurora,Borealis,Cosmos' && x.ct === 'application/json; charset=utf-8');
check('no file at startup', !fs.existsSync(path.join(d, 'b.json')));
